local a="create_radar:network_filterer_block_entity_0"local b=peripheral.wrap(a)assert(b,"Network Controller not found: "..a)assert(type(b.list)=="function"and type(b.size)=="function"and type(b.pullItems)=="function","Peripheral does not expose the expected inventory methods")local function c(d,e)print(d.." ("..tostring(e.size()).." slots):")local f=e.list()local g=false;for h=1,e.size()do local i=f[h]if i then g=true;local j=e.getItemDetail and e.getItemDetail(h)print("  Slot "..h..": "..tostring(j and(j.displayName or j.name)or i.name).." x"..tostring(i.count))end end;if not g then print("  (empty)")end end;local function k()local l=read()return tonumber(l)or tonumber(l:match("%d+"))end;c("Network Controller",b)print("\nAvailable source inventories:")local m={}for n,o in ipairs(peripheral.getNames())do if o~=a then local e=peripheral.wrap(o)if e and type(e.list)=="function"then m[#m+1]=o;print("  "..o)end end end;if#m==0 then print("No other inventory with pushItems is attached.")return end;print("\nPrepare an Identification Filter: hold it, open its GUI, and add a trusted test player.")print("Names in this filter are excluded from automatic targeting (they are treated as friendly).")print("Identification Filter belongs in controller slot 2. Keep cannon firing disabled for this test.")write("Source inventory name: ")local p=read()local q;for n,r in ipairs(m)do if r==p then q=r;break end;local s=r:match("[^:]+$")if s==p then if q then error("Ambiguous short name; enter the full peripheral name")end;q=r end end;q=q or p;local t=peripheral.wrap(q)if not t or type(t.list)~="function"then error("That source does not expose inventory methods")end;c("Selected source",t)write("Source slot containing the item (number, e.g. 1): ")local u=k()write("Network Controller destination slot (number, e.g. 1): ")local v=k()assert(u and u>=1 and u<=t.size(),"Invalid source slot")assert(v and v>=1 and v<=b.size(),"Invalid destination slot")assert(v==2,"Identification Filter must go into controller slot 2")local w=t.getItemDetail and t.getItemDetail(u)assert(w,"Selected source slot is empty")local x=w.displayName or w.name or"unknown item"local y=string.lower(tostring(w.name or"").." "..tostring(w.displayName or""))assert(y:find("ident",1,true),"Selected item does not look like an Identification Filter: "..tostring(x))assert(not b.list()[v],"Destination slot is occupied; choose an empty controller slot to avoid replacing a filter")print("\nWill pull exactly one "..tostring(x).." from "..q.." slot "..u.." into controller slot "..v..".")write("Type MOVE to perform this inventory transfer: ")if read()~="MOVE"then print("Cancelled; no items moved.")return end;local z,A=pcall(b.pullItems,q,u,1,v)if not z then error("pullItems failed: "..tostring(A))end;print("pullItems moved "..tostring(A).." item(s).")c("Network Controller after transfer",b)
